# ---------------- Filling the es/pt/it content ----------------
import re as _re
_EURO = _re.compile(r"^€(\d+)\.(\d\d)$")          # "€4.20" (a price in a mock-up) is written "4,20 €" in these languages
_SKIP = {"LEGAL_DOCS", "LANG_NAMES", "HTML_LANG", "OG_LOCALE", "SLUGS"}

def _tr(v, i, missing):
    if isinstance(v, str):
        t = T.get(v)
        if t: return t[i]
        m = _EURO.match(v)
        if m: return f"{m.group(1)},{m.group(2)} €"
        if _re.search(r"[A-Za-z]{2,}", _re.sub(r"<[^>]+>|\{\{PH:[^}]*\}\}|https?://\S+|[\w.+-]+@[\w.-]+", "", v)): missing.add(v)
        return v
    if isinstance(v, tuple): return tuple(_tr(x, i, missing) for x in v)
    if isinstance(v, list): return [_tr(x, i, missing) for x in v]
    if isinstance(v, dict): return {k: _tr(x, i, missing) for k, x in v.items()}
    return v

def _targets(obj, depth=0):
    """Every dict that holds one entry per language (it has "en" and "de" keys)."""
    if depth > 6 or not isinstance(obj, dict): return
    if {"en", "de"} <= {k for k in obj if isinstance(k, str)}:
        yield obj
        return
    for v in obj.values():
        yield from _targets(v, depth + 1)

def apply(ns, modules=()):
    """Adds es, pt and it next to "en" everywhere in build.py's namespace and in the given modules (extras and
    sectors_more, whose texts build.py reads directly). Returns the English texts that are not in T (they stay English)."""
    missing, seen = set(), set()
    roots = [v for k, v in ns.items() if not k.startswith("_") and k not in _SKIP and isinstance(v, dict)]
    for m in modules:
        roots += [v for k, v in vars(m).items() if not k.startswith("_") and k not in ("S", "SLUGS") and isinstance(v, dict)]
    for root in roots:
        for d in _targets(root):
            if id(d) in seen: continue
            seen.add(id(d))
            for i, l in enumerate(LANGS):
                if l not in d:                            # a text written for es/pt/it itself wins over the table
                    d[l] = _tr(d["en"], i, missing)
    for l, m in META.items():
        ns["LANG_NAMES"][l] = m["LANG_NAME"]; ns["HTML_LANG"][l] = m["HTML_LANG"]; ns["OG_LOCALE"][l] = m["OG_LOCALE"]
        for pid, slug in m["SLUGS"].items():
            if pid in ns["SLUGS"]: ns["SLUGS"][pid][l] = slug
        ns["LEGAL_DOCS"][l] = ns["LEGAL_DOCS"]["en"]      # the legal texts stay in English (the page says so)
    return sorted(missing)
